const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const {DatabaseSync}=require('node:sqlite');
const profile='C:/Users/Administrator/Desktop/project/DesktopPet/artifacts/qa/user-acceptance/e71b9c11-e62a-46a6-aa4d-decdd34c4200/local-b-concurrency';
const markerPath=path.join(profile,'.lingjing-qa-profile.json'),marker=JSON.parse(fs.readFileSync(markerPath));
const markerSha256=crypto.createHash('sha256').update(fs.readFileSync(markerPath)).digest('hex');
if(markerSha256!=='93c4f40ed59fe02854fcbbe7fe600a043b9a684cf9c45ec09ca30fa4142c0fcd'||marker.runId!=='4fe4b514-04d4-4832-98bc-c1128a1601f7'||path.resolve(marker.profilePath).toLowerCase()!==path.resolve(profile).toLowerCase())throw Error('Original LocalB marker required');
const db=new DatabaseSync(path.join(profile,'lingjing.sqlite'),{readOnly:true});
const allow=['account_settings','account_qa_profile','companion_accounts','companion_pets','companion_actions','conversation_profiles','conversation_preferences','conversation_messages','conversation_memories','battle_sessions','battle_action_receipts','battle_reward_receipts','battle_reports_v2','discovery_actions','discovery_encounters','discovery_captures','garden_accounts','garden_actions','garden_territory_attempts','garden_territory_challenges','garden_territory_records','garden_territory_logs','garden_garrisons'];
const canonical=x=>Array.isArray(x)?x.map(canonical):x&&typeof x==='object'?Object.fromEntries(Object.entries(x).sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>[k,canonical(v)])):x;
const report={at:new Date().toISOString(),profile,label:process.argv[2],marker,markerSha256,readOnly:true,queryOnly:true,credentialsRead:false,tables:{},digests:{}};
try{db.exec('PRAGMA query_only=ON; BEGIN');const known=new Set(db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all().map(r=>r.name));for(const table of allow.filter(t=>known.has(t))){const columns=db.prepare('PRAGMA table_info("'+table+'")').all().map(c=>c.name).filter(c=>!/(encrypted|password|proof|token|secret|private_key)/i.test(c));const rows=db.prepare('SELECT '+columns.map(c=>'"'+c+'"').join(',')+' FROM "'+table+'"').all();report.tables[table]=rows;report.digests[table]={count:rows.length,sha256:crypto.createHash('sha256').update(JSON.stringify(rows.map(canonical).sort((a,b)=>JSON.stringify(a).localeCompare(JSON.stringify(b))))).digest('hex')};}report.publicIdentities=db.prepare('SELECT owner_account_id,username,provider FROM account_identities').all();db.exec('COMMIT');}finally{db.close();}
const output=path.join(__dirname,'localB-'+report.label+'-20261026.json');fs.writeFileSync(output,JSON.stringify(report,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({output,at:report.at,markerSha256,identities:report.publicIdentities,counts:Object.fromEntries(Object.entries(report.digests).map(([t,v])=>[t,v.count])),settings:report.tables.account_settings?.map(r=>({revision:r.revision,document:JSON.parse(r.document)}))}));
